    La struttura di pagina (progress bar, uscita, colonna immagine, colonna
    contenuto) sta in layouts.missione-typ: qui solo il contenuto custom.
--}}
@extends('layouts.missione-typ')

@php
    /**
     * Recupero in modo puntuale le risposte del form.
     * I campi sono marcati in cms con il meta "borsafrigo".
     */

    // riepilogo: etichetta mostrata => risposta data
    $riepilogo = [
        'Destinazione'      => $formResponse->answerByQuestionMeta('borsafrigo', 'destinazione'),
        'Protagonista'      => $formResponse->answerByQuestionMeta('borsafrigo', 'protagonista'),
        'Compagno perfetto' => $formResponse->answerByQuestionMeta('borsafrigo', 'abbinamento'),
        'Momento ideale'    => $formResponse->answerByQuestionMeta('borsafrigo', 'momento'),
    ];

    // foto caricata dall'utente, va dentro la polaroid
    $foto = $formResponse->answerByQuestionMeta('borsafrigo', 'foto');
@endphp

@section('typ_content')


    {{--
        Intestazione congratulazioni.
        I testi maschile/femminile e il caso "genere non specificato"
        (//TODO: se utente non ha specificato genere? -> "Ottimo lavoro <nome>")
        stanno tutti nel componente condiviso.
    --}}
    <x-missioni.congratulazioni :user="$user" />

    <x-testi.testo size="text-sm" :txt="__('global.missioneCompletata-txt', ['num' => $activity->prize])" class="mt-3 max-w-[550px] mx-auto" :block=true />

