            <img src="{{ $foto ? Storage::disk('uploads')->url($foto->value) : asset("img/activities/custom/missione-borsafrigo/temp.jpg") }}" width="291" height="308" alt="image" class="absolute z-0 object-cover mt-8 ml-7 md:mt-10 md:ml-12 w-[220px] h-[230px] md:w-[291px] md:h-[308px]">

