        </picture>

        {{-- Risposte --}}

        <ul class="order-1 sm:order-2 text-black text-sm sm:text-left md:pb-10 sm:pl-5 md:pl-10">
            @foreach($riepilogo as $etichetta => $answer)
            @continue(!$answer)
            <li class="{{ $loop->first ? 'pb-5' : 'pb-3' }}">
                {{ $etichetta }}<br>
                <strong>{{ $answer->getAnswerLabel() }}</strong><br>
            </li>
            @endforeach
        </ul>

    </div>



    {{--
        bottone dashboard
