14	class MissioneRobiolaController extends Controller
15	{
16	    /**
17	     * Download the badge for a specific user activity.
18	     */
19	    public function badgeDownload(Request $request, int $userActivityId): BinaryFileResponse
20	    {
21	        $userActivity = UserActivity::findOrFail($userActivityId);
22	
23	        abort_if($userActivity->user_id !== $request->user()->id, 403);
24	
25	        $profile = $userActivity->extra_data['profile'] ?? null;
26	
27	        if (!$profile) {
28	            throw new \RuntimeException("UserActivity {$userActivityId} has no profile in extra_data.");
29	        }
30	
31	        $path = public_path('img/activities/custom/missione-robiola/badge-' . $profile . '.png');
32	
33	        if (!file_exists($path)) {
34	            throw new \RuntimeException("Badge file not found for profile '{$profile}': {$path}");
35	        }
36	
37	        return response()->download($path, 'badge-' . $profile . '.png');
38	    }
39	
40	    /**
41	     * Test: simula la thank-you page della Missione Robiola.
42	     *
43	     * Query params:
44	     *   ?profile=robioloso      profilo vincitore da mostrare (default: robioloso)
45	     *   ?user_id=456            forza un utente specifico (default: User::first())
46	     */
47	    public function testTyp(Request $request): View
48	    {
49	        $profile = $request->query('profile', 'robioloso');
50	        $userId  = $request->query('user_id');
51	
52	        $activity = Activity::where('response_processor_class', MissioneRobiolaProcessor::class)->firstOrFail();
53	
54	        $user = $userId
55	            ? User::findOrFail((int) $userId)
56	            : User::first();
57	
58	        // Costruisce dei punteggi di esempio con il profilo richiesto come vincitore
59	        $allProfiles = [$profile, 'altro-profilo'];
60	        $fakeScores  = array_combine($allProfiles, [5, 2]);
61	
62	        $fakeUserActivity = new UserActivity([
63	            'activity_id' => $activity->id,
64	            'extra_data' => [
65	                'scores'  => $fakeScores,
66	                'profile' => $profile,
67	            ],
68	        ]);
69	
70	        $thankYouMessage = __('global.missioneCompletata-txt', ['num' => $activity->prize]);
71	
72	        return view('activities.custom.missioneRobiola-typ', [
73	            'activity'        => $activity,
74	            'user'            => $user,
75	            'userActivity'    => $fakeUserActivity,
76	            'progressPercent' => 100,
77	            'thankYouMessage' => $thankYouMessage,
78	            'itsTheFirstTime' => true,
79	        ]);
80	    }
