3	namespace App\Http\Controllers\Activities;
4	
5	use App\Constraints\SendYourRecipeLimit;
6	use App\Domain\FormResponse\FormResponseAggregateRoot;
7	use App\Domain\UserActivity\Exceptions\ActivityAlreadyCompleted;
8	use App\Domain\UserActivity\Exceptions\ActivityCannotBeRunMultipleTimes;
9	use App\Domain\UserActivity\UserActivityAggregateRoot;
10	use App\Exceptions\Activities\MissingFormException;
11	use App\FormBuilder\Fields\FieldFactory;
12	use App\FormBuilder\Models\Form;
13	use App\FormBuilder\Models\FormResponse;
14	use App\Http\Middleware\ActivitiesPreviewForAdmin;
15	use App\Http\Requests\FormSectionRequest;
16	use App\Models\Activity;
17	use App\Models\User;
18	use App\Models\UserActivity;
19	use Exception;
20	use Illuminate\Http\RedirectResponse;
21	use Illuminate\Http\Request;
22	use Illuminate\Support\Facades\Auth;
23	use Illuminate\Support\Facades\File;
24	use Illuminate\Support\Facades\Storage;
25	use Illuminate\Support\Str;
26	use Illuminate\View\View;
27	use Throwable;
28	
29	class FormController extends \App\Http\Controllers\Controller
30	{
31	    public function __construct()
32	    {
33	        $this->middleware(['auth', ActivitiesPreviewForAdmin::class]);
34	
35	    }
36	
37	
38	    /**
39	     * This is a redirect page to start a new activity
40	     * flow.
41	     * It is hit via post when the user clicks on the "Start" button
42	     * on the activity cover page.
43	     * Creates a new activity flow or restore an existing one
44	     * if user is resuming an activity.
45	     * @param int $id id of the activity
46	     */
47	    public function start(Request $request, int $id): \Illuminate\Http\RedirectResponse
48	    {
49	
50	        /**
51	         * retrieve activity (specials included)
52	         * published scope is applied by the middleware ActivitiesPreviewForAdmin, if needed
53	         */
54	        $activity =  Activity::includeSpecials()->findOrFail($id);
55	
56	        /**
57	         * Check limit of activity replay
58	         */
59	        SendYourRecipeLimit::apply($activity, $request->user());
60	
61	        /**
62	         * Create a new activity flow or restore an existing one
63	         * if user is resuming an activity.
64	         */
65	        $uuid = $this->getUuid($request->user(), $activity);
66	        $currentFlow = UserActivity::findUuid($uuid);
67	
68	
69	        /**
70	         * If activity does not have a form or a form section,
71	         * redirect to the cover page.
72	         */
73	        if (!$activity->form || !$activity->form->sections->count()) {
74	            // throw new MissingFormException($activity->id);
75	            return redirect()->to($activity->coverUrl());
76	        }
77	
78	
79	        /**
80	         * create the sections order for the activity flow, based on form settings (randomization, lock first/last)
81	         */
82	        $currentFlow->createSectionsOrder($activity->form);
83	
84	        /**
85	         * Redirect to first section
86	         */
87	        $firstSection = $currentFlow->firstSection();
88	        return redirect()->to(route('missione-form', [
89	            'userActivityUuid' => $currentFlow->uuid,
90	            'sectionId' => $firstSection->id,
91	        ]));
92	    }
93	
94	
95	    /**
96	     * Show a single section of a form
97	     */
98	    public function section(Request $request): View|RedirectResponse
99	    {
100	
101	        /**
102	         * Retrieve user activity flow
103	         */
104	        $currentUserActivity = UserActivity::byUuid($request->userActivityUuid)->byUser($request->user())->firstOrFail();
105	        $formResponse = $currentUserActivity->formResponse;
106	        $formResponse->loadMissing('answers.question');
107	
108	
109	        /**
110	        * Retrieve activity (specials included)
111	        * (published scope is applied by the middleware ActivitiesPreviewForAdmin, if needed)
112	        */
113	        $activity =  Activity::includeSpecials()->findOrFail((int) $currentUserActivity->activity_id);
114	
115	        /**
116	         * Check limit of activity replay
117	         */
118	        SendYourRecipeLimit::apply($activity, $request->user());
119	
120	
121	        /**
122	         * Retrieve section, among the activity's form sections
123	         * to be sure that the section belongs to the activity
124	         */
125	        $section = $activity->form->sections()->with('fields')->findOrFail((int) $request->sectionId);
126	
127	
128	        /**
129	         * If activity flow is completed, user cannot be here.
130	         */
131	        if ($currentUserActivity->isCompleted()) {
132	            throw new ActivityAlreadyCompleted(
133	                userActivityId: $currentUserActivity->id,
134	                userId: $request->user()->id
135	            );
136	        }
137	
138	
139	        /**
140	         * Check all previous sections (in the user's ordered flow) are completed.
141	         * If not, redirect to the first incomplete section.
142	         * For activities created before the implementation of the sections order,
143	         * generate the order now to avoid errors.
144	         */
145	        if ($currentUserActivity->ordered_sections === null) {
146	            $currentUserActivity->createSectionsOrder($activity->form);
147	        }
148	        $orderedSectionIds = $currentUserActivity->ordered_sections;
149	        $currentIndex = array_search($section->id, $orderedSectionIds);
150	        if ($currentIndex !== false && $currentIndex > 0) {
151	            $previousIds = array_slice($orderedSectionIds, 0, $currentIndex);
152	            $previousSections = $activity->form->sections()->whereIn('id', $previousIds)->get()
153	                ->sortBy(fn ($s) => array_search($s->id, $orderedSectionIds));
154	            foreach ($previousSections as $previousSection) {
155	                if ($previousSection->isCompleted($formResponse) === false) {
156	                    return redirect()->to(route('missione-form', [
157	                        'userActivityUuid' => $currentUserActivity->uuid,
158	                        'sectionId' => $previousSection->id,
159	                    ]));
160	                }
161	            }
162	        }
163	
164	
165	        /**
166	         * Cicla tutti i campi e costruisce le corrispondenti
167	         * classi per il render del form
168	         */
169	        $fields = [];
170	        foreach ($section->fields->sortBy('sort') as $fieldModel) {
171	            try {
172	                $field = FieldFactory::fromModel($fieldModel);
173	
174	                $field->setUserActivity($currentUserActivity);
175	
176	                /**
177	                 * Resolve the options here, inside the try/catch: the real render happens
178	                 * in the view (Blade::renderComponent), i.e. outside this block, so without
179	                 * this call an error in the conditional filter of the options would surface
180	                 * as a bare 500, with no indication of which field caused it.
181	                 */
182	                if ($field->hasOptions()) {
183	                    $field->loadOptions();
184	                }
185	
186	
187	                // set old answer if field is not a file (otherwise will be managed by the livewire upload component)
188	                if ($field->isFile() === false) {
189	                    // if an answer exists, set it (in case user is resuming an activity),
190	                    // but give priority to the old value (in case of validation error)
191	                    $answer = old($field->getName());
192	                    if (!$answer) {
193	                        $answerModel = $formResponse->answers->where('field_id', $fieldModel->id)->first();
194	                        $answer = $answerModel ? $answerModel->value : $answer;
195	                    }
196	                    if ($answer) {
197	                        $field->setAnswer($answer);
198	                    }
199	                }
200	
201	
202	                $fields[] = $field;
203	
204	
205	            } catch (Throwable $e) {
206	                throw new Exception("Errore nel render del campo {$fieldModel->id} {$fieldModel->field_type->name} : {$e->getMessage()}");
207	            }
208	        }
209	
210	        /**
211	         * Retrieve previous section, to show the "back" button.
212	         * If no previous section exists, go back to the "cover" page.
213	         */
214	        $previousSection = $currentUserActivity->prevSection($section);
215	        $backLink = $previousSection ? route('missione-form', [
216	            'userActivityUuid' => $currentUserActivity->uuid,
217	            'sectionId' => $previousSection->id,
218	        ]) : $activity->coverUrl();
219	
220	
221	        $viewName = $section->custom_view ? 'activities.custom.'.$section->custom_view : 'activities.section';
222	
223	        // @phpstan-ignore argument.type
224	        return view($viewName, [
225	            'activity' => $activity,
226	            'section' => $section,
227	            'fields' => collect($fields),
228	            'user_activity_uuid' => $currentUserActivity->uuid,
229	            'backLink' => $backLink,
230	            'progressPercent' => $this->progress($formResponse),
