240	    /**
241	     * Logic to retrieve / create the uuid of the form response,
242	     * depending on whether the user has already done the activity or not,
243	     * it is resuming or starting a new activity, etc..
244	     * Return the uuid of the activity (UserActivity), resumed or new.
245	     */
246	    public function getUuid(User $user, Activity $activity): ?string
247	    {
248	
249	        // check if a record exists in the activity_user table
250	        $existingActivityFlow = UserActivity::where('user_id', $user->id)
251	            ->where('activity_id', $activity->id)
252	            ->first();
253	        $formResponse = $existingActivityFlow?->formResponse;
254	
255	
256	        /**
257	         * If form response exists but activity is not completed, user is resuming an activity.
258	         * (replayable or not).
259	         * Return current flow uuid.
260	         */
261	        if ($formResponse !== null && $existingActivityFlow->isCompleted() === false) {
262	            return $existingActivityFlow->uuid;
263	        }
264	
265	
266	        /**
267	         * If response exists and activity is completed, user is restarting an activity.
268	         * Activity must be replayable to allow this.
269	         */
270	        if (
271	            $formResponse !== null
272	            && $existingActivityFlow->isCompleted() === true
273	            && $activity->canBePlayed($user) === false
274	        ) {
275	            throw new ActivityCannotBeRunMultipleTimes(
276	                $activity->id,
277	                $user->id
278	            );
279	        }
280	
281	        /**
282	         * At this point, we know that the user is starting a new activity.
283	         * (for the first time or because the previous one was completed).
284	         */
285	        $formResponse = FormResponse::create([
286	            'form_id' => $activity->form->id,
287	            'user_id' => $user->id,
288	            'uuid' => Str::uuid(),
289	        ]);
290	        $newActivityUiid = Str::uuid();
291	        UserActivityAggregateRoot::retrieve($newActivityUiid)
292	            ->beginActivity(
293	                $activity,
294	                $user,
295	                $formResponse,
296	            )->persist();
297	
298	        return $newActivityUiid;
299	    }
