302	    /**
303	     * Submit a section of the form.
304	     * Save answers to the database, for the current form section.
305	     * See FormSectionRequest for validation rules.
306	     * When saving is complete, redirect to the next section.
307	     */
308	    public function submitSection(FormSectionRequest $request): \Illuminate\Http\RedirectResponse
309	    {
310	        $data = $request->validated();
311	
312	        $userActivity = $request->userActivity;
313	        $activity = $request->activity;
314	
315	
316	        /**
317	         * Handle double-submit gracefully (frequent on mobile clients): if this flow
318	         * is already completed, the activity is done — redirect to the thank you page
319	         * instead of reprocessing the submit and triggering ActivityCannotBeCompletedMultipleTimes.
320	         */
321	        if ($userActivity->isCompleted()) {
322	            return redirect()->to(route('missione-completata', [
323	                'userActivityUuid' => $userActivity->uuid,
324	            ]))
325	            ->with('success', true);
326	        }
327	
328	
329	        /**
330	         * Check limit of activity replay
331	         */
332	        SendYourRecipeLimit::apply($activity, $request->user());
333	
334	
335	        // retrieve form response aggragate
336	        $formResponseAR = FormResponseAggregateRoot::retrieve($userActivity->formResponse->uuid);
337	
338	        // save answers
339	        foreach ($request->formSection->fields as $field) {
340	
341	            $formField = FieldFactory::fromModel($field);
342	
343	            // retrieve answer from request
344	            $answer = $data[$formField->getName()] ?? null;
345	
346	            // if the field is a file, it is managed by the livewire component if a file was uploaded.
347	            // if a file was not uploaded $answer is null (eg. the field was not required and user did not upload a file),
348	            // the answer is not saved so we have to create an empty response in order to complete the section.
349	            if ($formField->isFile()) {
350	
351	                $aFileWasUploaded = $answer !== null;
352	                if ($aFileWasUploaded === false) {
353	                    $formResponseAR->giveAnswer(
354	                        $field,
355	                        $answer
356	                    );
357	                }
358	
359	            } else {
360	                $formResponseAR->giveAnswer(
361	                    $field,
362	                    $answer
363	                );
364	            }
365	
366	        }
367	        $formResponseAR->persist();
368	
369	        // load next section
370	        $nextSection = $userActivity->nextSection($request->formSection);
371	
372	
373	        /**
374	         * if no next section exists, complete the activity
375	         * and redirect to the thank you page
376	         */
377	        if (!$nextSection) {
378	
379	            /** @disregard P1013 */
380	            UserActivityAggregateRoot::retrieve($userActivity->uuid)
381	                ->completeActivity(
382	                    $request->activity,
383	                    $request->user(),
384	                )->persist();
385	
386	            return redirect()->to(route('missione-completata', [
387	                'userActivityUuid' => $request->userActivity->uuid,
388	            ]))
389	            ->with('success', true);
390	        }
391	
392	        return redirect()->to(route('missione-form', [
393	            'userActivityUuid' => $userActivity->uuid,
394	            'sectionId' => $nextSection->id,
395	        ]));
396	
397	    }
