439	    /**
440	     * Thank you page for the activity.
441	     * This page can be viewed multiple times,
442	     * but only if the activity is completed.
443	     */
444	    public function success(Request $request): View
445	    {
446	        $userActivity = UserActivity::byUuid($request->userActivityUuid)
447	            ->byUser($request->user())
448	            ->firstOrFail();
449	
450	        /**
451	         * Retrive activity (specials included)
452	         * published scope is applied by the middleware ActivitiesPreviewForAdmin, if needed
453	         */
454	        $activity =  Activity::includeSpecials()->findOrFail((int) $userActivity->activity_id);
455	
456	        // activity must be completed at this point
457	        if ($userActivity->isCompleted() === false) {
458	            throw new Exception("Activity not completed");
459	        }
460	
461	
462	        /**
463	         * Thank you message
464	         */
465	        $thankYouMessage = '';
466	
467	        // show prize only if activity is completed for the first time or if activity is cumulable
468	        if ($activity->cumulable === true || Auth::user()->completedActivityCount($activity->id) === 1) {
469	            $thankYouMessage = __('global.missioneCompletata-txt', ['num' => $activity->prize]);
470	        }
471	        // extra thank you message, visible even if activity is replayed
472	        if ($activity->getTranslation('extra_thankyou_message', app()->getLocale())) {
473	            if (strlen($thankYouMessage) > 0) {
474	                $thankYouMessage .= '<br>';
475	            }
476	            $thankYouMessage .= $activity->getTranslation('extra_thankyou_message', app()->getLocale());
477	        }
478	
479	        // custom message for "send your recipe"
480	        if ($activity->special_code === 'send_recipe') {
481	            $thankYouMessage = __('global.missioneCompletata-ricetta-txt', ['num' => $activity->prize]);
482	        }
483	
484	
485	        // load custom thankyou page if defined
486	        $view = $activity->custom_typ_view ? 'activities.custom.'.$activity->custom_typ_view : 'activities.missione-completata';
487	
488	        $user = $request->user();
489	        // @phpstan-ignore argument.type
490	        return view($view, [
491	            'activity' => $activity,
492	            'user' => $user,
493	            'userActivity' => $userActivity,
494	            'progressPercent' => $this->progress($userActivity->formResponse),
495	            'formResponse' => $userActivity->formResponse,
496	            'thankYouMessage' => $thankYouMessage,
497	            // Show prize message only if activity is completed for the first time
498	            'itsTheFirstTime' => $user->completedActivityCount($activity->id, function ($query) use ($userActivity) {
