506	     * Calculate the progress of the activity.
507	     */
508	    public function progress(FormResponse $formResponse): float
509	    {
510	
511	        /**
512	         * Calculate progress
513	         * (based on fields, not sections)
514	         */
515	        $totalFields = $formResponse->form->fields()->count();
516	        if ($totalFields === 0) {
517	            return 0;
518	        }
519	        $progressPercent = floor($formResponse->answers->count() / $totalFields * 100);
520	
521	        return $progressPercent;
522	
