3	namespace App\Domain\UserActivity\ResponseProcessors;
4	
5	use App\FormBuilder\Models\FormFieldOption;
6	use App\FormBuilder\Models\FormResponseField;
7	use App\Models\UserActivity;
8	
9	class MissioneRobiolaProcessor
10	{
11	    public function process(UserActivity $userActivity): void
12	    {
13	        $userActivity->loadMissing('formResponse.answers.question.options');
14	
15	        $scores = [];
16	        $profileOrder = []; // tracks the order in which profiles first receive points
17	
18	        /** @var FormResponseField $answer */
19	        foreach ($userActivity->formResponse->answers as $answer) {
20	
21	            $field = $answer->question;
22	
23	            // skip fields that don't have options
24	            if (!$field->field_type->factory($field)->hasOptions()) {
25	                continue;
26	            }
27	
28	            // normalize answer value(s) to an array
29	            $chosenValues = is_array($answer->value) ? $answer->value : [$answer->value];
30	
31	            // find the chosen options and accumulate scores from their meta
32	            foreach ($field->options as $option) {
33	                if (!in_array($option->value, $chosenValues, true)) {
34	                    continue;
35	                }
36	
37	                // get points from chosen option meta and accumulate them
38	                $this->accumulateScores($scores, $profileOrder, $option);
39	            }
40	        }
41	
42	        $profile = $this->determineProfile($scores, $profileOrder);
43	
44	        $userActivity->extra_data = ['scores' => $scores, 'profile' => $profile];
45	        $userActivity->save();
46	    }
47	
48	    /**
49	     * Extract score meta keys from an option and add them to the accumulator.
50	     * Meta keys with prefix "punti-" are treated as profile scores.
51	     * e.g. a meta key "punti-robio" with value 2 will add 2 points to the "robio" profile.
52	     *
53	     * @param array<string, int|float> $scores
54	     * @param array<int, string> $profileOrder
55	     */
56	    private function accumulateScores(array &$scores, array &$profileOrder, FormFieldOption $option): void
57	    {
58	        /** @var array<string, mixed>|null $meta */
59	        $meta = $option->meta;
60	
61	        if (!is_array($meta)) {
62	            return;
63	        }
64	
65	        foreach ($meta as $key => $value) {
66	            if (!str_starts_with((string) $key, 'punti-')) {
67	                continue;
68	            }
69	
70	            // extract profile name from meta key, e.g. "punti-robio" => "robio"
71	            // and stores in profile order if not already there, to determine the winner in case of tie scores
72	            $profile = substr((string) $key, strlen('punti-'));
73	            if (!in_array($profile, $profileOrder, true)) {
74	                $profileOrder[] = $profile;
75	            }
76	            $scores[$profile] = ($scores[$profile] ?? 0) + (int) $value;
77	        }
78	    }
79	
80	
81	    /**
82	     * @param array<string, int|float> $scores
83	     * @param array<int, string> $profileOrder order in which profiles first received points
84	     */
85	    private function determineProfile(array $scores, array $profileOrder): ?string
86	    {
87	        if (empty($scores)) {
88	            return null;
89	        }
90	
91	        $maxScore = max($scores);
92	
93	        // among tied profiles, the one that received a response first wins
94	        foreach ($profileOrder as $profile) {
95	            if ($scores[$profile] === $maxScore) {
96	                return $profile;
97	            }
98	        }
99	
100	        return null;
101	    }
102	}
