1	<?php
2	
3	namespace App\Domain\UserActivity\Projectors;
4	
5	use App\Domain\User\Events\ActivityImported;
6	use App\Domain\UserActivity\Events\ActivityBegun;
7	use App\Domain\UserActivity\Events\ActivityCompleted;
8	use App\FormBuilder\Models\FormResponse;
9	use App\Models\Activity;
10	use App\Models\User;
11	use App\Models\UserActivity;
12	use Exception;
13	use Illuminate\Support\Str;
14	use Spatie\EventSourcing\EventHandlers\Projectors\Projector;
15	
16	class UserActivityProjector extends Projector
17	{
18	    /**
19	     * Here you can specify which event should trigger which method.
20	     * @var array<string,string>
21	     */
22	    protected array $handlesEvents = [
23	        ActivityBegun::class => 'onActivityBegun',
24	        ActivityCompleted::class => 'onActivityCompleted',
25	    ];
26	
27	
28	
29	    /**
30	     * An activity has begun.
31	     * Create a relation record with the user and the activity
32	     */
33	    public function onActivityBegun(ActivityBegun $event): void
34	    {
35	
36	        /**
37	         * retrieve related models
38	         */
39	        $user = User::findUuid($event->userUuid);
40	        $formResponse = $event->formResponseUuid ? FormResponse::findUuid($event->formResponseUuid) : null;
41	
42	        /**
43	         * Create a relation record with the user and the activity
44	         */
45	        UserActivity::create([
46	            'uuid' => $event->aggregateRootUuid(),
47	            'user_id' => $user->id,
48	            'activity_id' => $event->activityId,
49	            'form_response_id' => $formResponse?->id,
50	        ]);
51	
52	    }
53	
54	
55	    /**
56	     * An activity has been completed.
57	     */
58	    public function onActivityCompleted(ActivityCompleted $event): void
59	    {
60	
61	        $userActivity = UserActivity::where('uuid', $event->aggregateRootUuid())->first();
62	
63	        /**
64	         * Update the relation record with the user and the activity
65	         */
66	        $userActivity->update(
67	            [
68	                'completed_at' => $event->createdAt(),
69	                'product_id' => $event->productId ?? null,
70	            ]
71	        );
72	
73	        /**
74	         * call custom response processor if configured for the activity
75	         */
76	        $this->callResponseProcessor($userActivity);
77	
78	    }
79	
80	
81	    /**
82	     * An activity has been imported from the old system.
83	     * This event is triggered by the UserAggregateRoot
84	     * and it is binded to the user uuid.
85	     * We manage it here for the sake of consistency
86	     * with the other activity events.
87	     */
88	    public function onActivityImported(ActivityImported $event): void
89	    {
90	
91	        /**
92	         * Retrieve the user by uuid
93	         */
94	        $user = User::findUuid($event->aggregateRootUuid());
95	        if (!$user) {
96	            throw new Exception("User with uuid [{$event->aggregateRootUuid()}] not found");
97	        }
98	
99	
100	        /**
101	         * The activity flow cannot exist already.
102	         */
103	        $activityFlow = UserActivity::where([
104	            'user_id' => $user->id,
105	            'activity_id' => $event->activityId,
106	        ]);
107	        if ($activityFlow->exists()) {
108	            throw new \Exception("Activity flow for user [{$user->id}] and activity [{$event->activityId}] already exists.");
109	        }
110	
111	
112	        /**
113	         * Create a new activity flow for the user
114	         */
115	        $activityFlow = UserActivity::create([
116	            'uuid' => Str::uuid(), //  must be a new uuid!
117	            'user_id' => $user->id,
118	            'activity_id' => $event->activityId,
119	            'completed_at' => $event->completedAt,
120	        ]);
121	
122	    }
123	
124	    /**
125	     * Call the response processor associated with the activity, if any.
126	     */
127	    protected function callResponseProcessor(UserActivity $userActivity): void
128	    {
129	        $activity = Activity::includeSpecials()->find($userActivity->activity_id);
130	        $processorClass = $activity?->response_processor_class;
131	        if (!$processorClass) {
132	            return;
133	        }
134	
135	        if (!class_exists($processorClass)) {
136	            throw new Exception("Response processor class [{$processorClass}] not found.");
137	        }
138	
139	        $processor = app($processorClass);
140	        if (!method_exists($processor, 'process')) {
141	            throw new Exception("Response processor class [{$processorClass}] does not have a process method.");
142	        }
143	
144	        // @phpstan-ignore method.nonObject
145	        $processor->process($userActivity);
146	    }
147	
148	
149	}
