11	
12	class MissioneBorsaFrigoController extends Controller
13	{
14	    /**
15	     * Dimensioni (in px) della cornice polaroid, vedi
16	     * public/img/activities/custom/missione-borsafrigo/polaroid.png
17	     */
18	    private const FRAME_WIDTH = 766;
19	    private const FRAME_HEIGHT = 886;
20	
21	    /**
22	     * Riquadro foto dentro la cornice: stesse proporzioni usate
23	     * nella thank you page (typ.blade.php), scalate 2x per la risoluzione nativa.
24	     */
25	    private const PHOTO_WIDTH = 582;
26	    private const PHOTO_HEIGHT = 616;
27	    private const PHOTO_OFFSET_X = 96;
28	    private const PHOTO_OFFSET_Y = 80;
29	
30	    /**
31	     * Compone la foto caricata dall'utente con la cornice polaroid
32	     * e restituisce l'immagine risultante come download.
33	     */
34	    public function downloadImage(Request $request, int $userActivityId): Response
35	    {
36	        $userActivity = UserActivity::findOrFail($userActivityId);
37	
38	        abort_if($userActivity->user_id !== $request->user()->id, 403);
39	
40	        $foto = $userActivity->formResponse->answerByQuestionMeta('borsafrigo', 'foto');
41	
42	        abort_if(!$foto, 404, 'Nessuna foto trovata per questa missione.');
43	
44	        $userPhotoPath = Storage::disk('uploads')->path($foto->value);
45	        $framePath = public_path('img/activities/custom/missione-borsafrigo/polaroid.png');
46	
47	
48	        // crea frame
49	        $canvas = Image::canvas(self::FRAME_WIDTH, self::FRAME_HEIGHT, '#ffffff');
50	
51	        // inserisce immagine utente in frame (modalità "fit")
52	        $canvas->insert(
53	            Image::make($userPhotoPath)->fit(self::PHOTO_WIDTH, self::PHOTO_HEIGHT),
54	            'top-left',
55	            self::PHOTO_OFFSET_X,
56	            self::PHOTO_OFFSET_Y
57	        );
58	        $canvas->insert(Image::make($framePath), 'top-left', 0, 0);
59	
60	        $encoded = $canvas->encode('png');
61	
62	        return response($encoded->getEncoded(), 200, [
63	            'Content-Type' => 'image/png',
64	            'Content-Disposition' => 'attachment; filename="la-tua-borsa-frigo.png"',
65	        ]);
66	    }
67	}
