1	<?php
2	
3	namespace App\Domain\UserActivity\Services;
4	
5	use App\Models\UserActivity;
6	use Illuminate\Support\Facades\Storage;
7	use Intervention\Image\Facades\Image;
8	use Intervention\Image\Image as InterventionImage;
9	
10	/**
11	 * Compone la foto caricata dall'utente nella missione "borsa frigo" con la
12	 * cornice polaroid, in un'unica immagine scaricabile.
13	 * Usato sia dal response processor (generazione al completamento missione)
14	 * sia dal controller di download (fallback per attività completate prima
15	 * che questa generazione esistesse, o se la generazione al completamento
16	 * è fallita).
17	 */
18	class BorsaFrigoPolaroidComposer
19	{
20	    /**
21	     * Dimensioni (in px) della cornice polaroid, vedi
22	     * public/img/activities/custom/missione-borsafrigo/polaroid.png
23	     */
24	    private const FRAME_WIDTH = 766;
25	    private const FRAME_HEIGHT = 886;
26	
27	    /**
28	     * Riquadro foto dentro la cornice: stesse proporzioni usate
29	     * nella thank you page (typ.blade.php), scalate 2x per la risoluzione nativa.
30	     */
31	    private const PHOTO_WIDTH = 582;
32	    private const PHOTO_HEIGHT = 616;
33	    private const PHOTO_OFFSET_X = 96;
34	    private const PHOTO_OFFSET_Y = 80;
35	
36	    /** Cartella, sul disk "uploads", in cui salvare le immagini composte. */
37	    private const STORAGE_FOLDER = 'borsa-frigo-polaroid';
38	
39	    /**
40	     * Compone la foto utente con la cornice e restituisce l'immagine risultante (PNG).
41	     */
42	    public function compose(string $userPhotoPath): InterventionImage
43	    {
44	        $framePath = public_path('img/activities/custom/missione-borsafrigo/polaroid.png');
45	
46	        $canvas = Image::canvas(self::FRAME_WIDTH, self::FRAME_HEIGHT, '#ffffff');
47	
48	        $canvas->insert(
49	            Image::make($userPhotoPath)->fit(self::PHOTO_WIDTH, self::PHOTO_HEIGHT),
50	            'top-left',
51	            self::PHOTO_OFFSET_X,
52	            self::PHOTO_OFFSET_Y
53	        );
54	        $canvas->insert(Image::make($framePath), 'top-left', 0, 0);
55	
56	        return $canvas->encode('png');
57	    }
58	
59	    /**
60	     * Compone la polaroid per una user activity e la salva sul disk "uploads".
61	     * Ritorna il path relativo salvato, o null se l'utente non ha caricato una foto.
62	     */
63	    public function composeAndStore(UserActivity $userActivity): ?string
64	    {
65	        $userActivity->loadMissing('formResponse');
66	
67	        $foto = $userActivity->formResponse?->answerByQuestionMeta('borsafrigo', 'foto');
68	
69	        if (!$foto) {
70	            return null;
71	        }
72	
73	        $userPhotoPath = Storage::disk('uploads')->path($foto->value);
74	
75	        $composed = $this->compose($userPhotoPath);
76	
77	        $relativePath = self::STORAGE_FOLDER . '/' . $userActivity->uuid . '.png';
78	
79	        Storage::disk('uploads')->put($relativePath, (string) $composed);
80	
81	        return $relativePath;
82	    }
83	}
84

